-- 001_initial_schema.sql
-- Complete database schema for TaskReward Platform
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('USER','ADMIN','SUPER_ADMIN','SUPPORT','FINANCE','MODERATOR'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE user_status AS ENUM ('PAYMENT_PENDING','ACTIVE','REJECTED','SUSPENDED','BANNED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE risk_level AS ENUM ('NORMAL','WATCH','FLAGGED','SUSPENDED','BANNED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE payment_status AS ENUM ('PENDING','APPROVED','REJECTED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE task_status AS ENUM ('DRAFT','ACTIVE','PAUSED','ARCHIVED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE submission_status AS ENUM ('PENDING','APPROVED','REJECTED','FLAGGED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE withdrawal_status AS ENUM ('PENDING','APPROVED','PROCESSING','PAID','REJECTED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE membership_status AS ENUM ('PENDING_PAYMENT','ACTIVE','EXPIRING','EXPIRED','SUSPENDED','BANNED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE wallet_tx_type AS ENUM ('TASK_REWARD','WITHDRAWAL','WITHDRAWAL_REVERSED','ADMIN_ADJUSTMENT','REGISTRATION_PAYMENT','BONUS','PENALTY','REFUND','REFERRAL'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE wallet_tx_status AS ENUM ('PENDING','COMPLETED','REVERSED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE ticket_status AS ENUM ('OPEN','IN_PROGRESS','WAITING','RESOLVED','CLOSED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE announcement_type AS ENUM ('INFO','SUCCESS','WARNING','IMPORTANT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE notification_type AS ENUM ('INFO','SUCCESS','WARNING','IMPORTANT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS profiles (id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, email TEXT UNIQUE NOT NULL, username TEXT UNIQUE NOT NULL, full_name TEXT NOT NULL, phone TEXT, password_hash TEXT, role user_role NOT NULL DEFAULT 'USER', status user_status NOT NULL DEFAULT 'PAYMENT_PENDING', risk_level risk_level NOT NULL DEFAULT 'NORMAL', profile_image TEXT, referral_code TEXT UNIQUE NOT NULL DEFAULT uuid_generate_v4(), referred_by_id UUID REFERENCES profiles(id) ON DELETE SET NULL, balance DECIMAL(12,2) NOT NULL DEFAULT 0, pending_balance DECIMAL(12,2) NOT NULL DEFAULT 0, total_earned DECIMAL(12,2) NOT NULL DEFAULT 0, total_withdrawn DECIMAL(12,2) NOT NULL DEFAULT 0, flagged BOOLEAN NOT NULL DEFAULT FALSE, flagged_reason TEXT, last_login_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT balance_non_negative CHECK (balance >= 0), CONSTRAINT pending_balance_non_negative CHECK (pending_balance >= 0));
CREATE INDEX IF NOT EXISTS idx_profiles_status ON profiles(status);
CREATE INDEX IF NOT EXISTS idx_profiles_role ON profiles(role);
CREATE INDEX IF NOT EXISTS idx_profiles_referred_by ON profiles(referred_by_id);
CREATE INDEX IF NOT EXISTS idx_profiles_email ON profiles(email);
CREATE TABLE IF NOT EXISTS site_settings (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), key TEXT UNIQUE NOT NULL, value TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT 'GENERAL', type TEXT NOT NULL DEFAULT 'STRING', updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_by UUID REFERENCES profiles(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS feature_flags (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), key TEXT UNIQUE NOT NULL, name TEXT NOT NULL, description TEXT, enabled BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_by UUID REFERENCES profiles(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS payment_methods (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, description TEXT, enabled BOOLEAN NOT NULL DEFAULT TRUE, account_name TEXT, account_number TEXT, wallet_address TEXT, network TEXT, qr_code_url TEXT, instructions TEXT, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS registration_payments (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, payment_method_id UUID NOT NULL REFERENCES payment_methods(id), sender_name TEXT NOT NULL, sender_account TEXT NOT NULL, transaction_id TEXT NOT NULL, amount DECIMAL(12,2) NOT NULL CHECK (amount > 0), payment_date TIMESTAMPTZ NOT NULL, screenshot_url TEXT NOT NULL, note TEXT, status payment_status NOT NULL DEFAULT 'PENDING', admin_note TEXT, reviewed_by_id UUID REFERENCES profiles(id) ON DELETE SET NULL, reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_reg_payments_status ON registration_payments(status);
CREATE INDEX IF NOT EXISTS idx_reg_payments_user ON registration_payments(user_id);
CREATE TABLE IF NOT EXISTS membership_plans (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT UNIQUE NOT NULL, description TEXT, monthly_fee DECIMAL(12,2) NOT NULL DEFAULT 0, initial_fee DECIMAL(12,2) NOT NULL DEFAULT 0, task_access TEXT NOT NULL DEFAULT 'ALL', daily_task_limit INTEGER NOT NULL DEFAULT 0, withdrawal_min DECIMAL(12,2) NOT NULL DEFAULT 0, withdrawal_max DECIMAL(12,2) NOT NULL DEFAULT 0, referral_bonus_multiplier DECIMAL(3,2) NOT NULL DEFAULT 1.0, active BOOLEAN NOT NULL DEFAULT TRUE, is_default BOOLEAN NOT NULL DEFAULT FALSE, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID UNIQUE NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, plan_id UUID NOT NULL REFERENCES membership_plans(id), status membership_status NOT NULL DEFAULT 'PENDING_PAYMENT', started_at TIMESTAMPTZ, current_period_start TIMESTAMPTZ, current_period_end TIMESTAMPTZ, next_payment_due TIMESTAMPTZ, fee DECIMAL(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_memberships_status ON memberships(status);
CREATE TABLE IF NOT EXISTS membership_payments (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), membership_id UUID NOT NULL REFERENCES memberships(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, payment_method_id UUID NOT NULL REFERENCES payment_methods(id), sender_name TEXT NOT NULL, sender_account TEXT NOT NULL, transaction_id TEXT NOT NULL, amount DECIMAL(12,2) NOT NULL CHECK (amount > 0), payment_date TIMESTAMPTZ NOT NULL, screenshot_url TEXT NOT NULL, note TEXT, billing_period_start TIMESTAMPTZ, billing_period_end TIMESTAMPTZ, status payment_status NOT NULL DEFAULT 'PENDING', admin_note TEXT, reviewed_by_id UUID REFERENCES profiles(id) ON DELETE SET NULL, reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_membership_payments_status ON membership_payments(status);
CREATE TABLE IF NOT EXISTS task_categories (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT UNIQUE NOT NULL, description TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), title TEXT NOT NULL, platform TEXT NOT NULL DEFAULT 'TikTok', type TEXT NOT NULL, target_url TEXT NOT NULL, profile_url TEXT, instructions TEXT NOT NULL, reward DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK (reward >= 0), status task_status NOT NULL DEFAULT 'DRAFT', max_completions INTEGER NOT NULL DEFAULT 0, current_completions INTEGER NOT NULL DEFAULT 0, start_date TIMESTAMPTZ, end_date TIMESTAMPTZ, category_id UUID REFERENCES task_categories(id) ON DELETE SET NULL, screenshot_required BOOLEAN NOT NULL DEFAULT TRUE, text_proof_required BOOLEAN NOT NULL DEFAULT FALSE, link_proof_required BOOLEAN NOT NULL DEFAULT FALSE, priority INTEGER NOT NULL DEFAULT 0, visibility TEXT NOT NULL DEFAULT 'PUBLIC', daily_limit INTEGER NOT NULL DEFAULT 0, estimated_time TEXT NOT NULL DEFAULT '2-3 min', created_by_id UUID NOT NULL REFERENCES profiles(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_tasks_status ON tasks(status);
CREATE TABLE IF NOT EXISTS task_submissions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, screenshot_url TEXT, text_proof TEXT, link_proof TEXT, status submission_status NOT NULL DEFAULT 'PENDING', admin_note TEXT, ip_address TEXT, device_info TEXT, reviewed_by_id UUID REFERENCES profiles(id) ON DELETE SET NULL, reviewed_at TIMESTAMPTZ, reward_credited BOOLEAN NOT NULL DEFAULT FALSE, reward_amount DECIMAL(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uniq_task_user UNIQUE (task_id, user_id));
CREATE INDEX IF NOT EXISTS idx_submissions_status ON task_submissions(status);
CREATE TABLE IF NOT EXISTS wallets (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID UNIQUE NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, balance DECIMAL(12,2) NOT NULL DEFAULT 0, pending_balance DECIMAL(12,2) NOT NULL DEFAULT 0, total_earned DECIMAL(12,2) NOT NULL DEFAULT 0, total_withdrawn DECIMAL(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wallet_transactions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, type wallet_tx_type NOT NULL, amount DECIMAL(12,2) NOT NULL, balance_before DECIMAL(12,2) NOT NULL, balance_after DECIMAL(12,2) NOT NULL, reference_type TEXT, reference_id TEXT, description TEXT NOT NULL, status wallet_tx_status NOT NULL DEFAULT 'COMPLETED', created_by UUID REFERENCES profiles(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_wallet_tx_user ON wallet_transactions(user_id);
CREATE TABLE IF NOT EXISTS withdrawals (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, amount DECIMAL(12,2) NOT NULL CHECK (amount > 0), fee DECIMAL(12,2) NOT NULL DEFAULT 0, payment_method_id UUID NOT NULL REFERENCES payment_methods(id), payout_account_id UUID, payout_account_holder TEXT NOT NULL, payout_account_number TEXT NOT NULL, payout_wallet_address TEXT, payout_network TEXT, note TEXT, status withdrawal_status NOT NULL DEFAULT 'PENDING', admin_note TEXT, payment_transaction_id TEXT, payment_proof_url TEXT, reviewed_by_id UUID REFERENCES profiles(id) ON DELETE SET NULL, reviewed_at TIMESTAMPTZ, paid_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_withdrawals_status ON withdrawals(status);
CREATE TABLE IF NOT EXISTS payout_accounts (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, payment_method_id UUID NOT NULL REFERENCES payment_methods(id), account_holder_name TEXT, account_number TEXT, wallet_address TEXT, network TEXT, label TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, title TEXT NOT NULL, message TEXT NOT NULL, type notification_type NOT NULL DEFAULT 'INFO', is_read BOOLEAN NOT NULL DEFAULT FALSE, link TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS announcements (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), title TEXT NOT NULL, message TEXT NOT NULL, type announcement_type NOT NULL DEFAULT 'INFO', active BOOLEAN NOT NULL DEFAULT TRUE, start_date TIMESTAMPTZ NOT NULL DEFAULT now(), end_date TIMESTAMPTZ, target_audience TEXT NOT NULL DEFAULT 'ALL', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referrals (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), referrer_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, referred_id UUID UNIQUE NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referral_transactions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), referrer_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, referred_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, amount DECIMAL(12,2) NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bonuses (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT NOT NULL, type TEXT NOT NULL, amount DECIMAL(12,2) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, conditions TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_bonuses (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, bonus_id UUID NOT NULL REFERENCES bonuses(id) ON DELETE CASCADE, amount DECIMAL(12,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_limits (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID UNIQUE NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, daily_task_count INTEGER NOT NULL DEFAULT 0, daily_withdrawal_amount DECIMAL(12,2) NOT NULL DEFAULT 0, last_task_date TIMESTAMPTZ, last_withdrawal_date TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_overrides (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID UNIQUE NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, custom_min_withdrawal DECIMAL(12,2), custom_max_withdrawal DECIMAL(12,2), custom_daily_withdrawal DECIMAL(12,2), custom_task_access TEXT, custom_daily_task_limit INTEGER, custom_membership_status TEXT, custom_membership_expiry TIMESTAMPTZ, referral_eligible BOOLEAN, bonus_eligible BOOLEAN, notes TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tags (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT UNIQUE NOT NULL, color TEXT NOT NULL DEFAULT 'gray', description TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_tags (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, tag_id UUID NOT NULL REFERENCES tags(id) ON DELETE CASCADE, created_by UUID REFERENCES profiles(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uniq_user_tag UNIQUE (user_id, tag_id));
CREATE TABLE IF NOT EXISTS user_notes (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, admin_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, note TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_tickets (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, subject TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'GENERAL', priority TEXT NOT NULL DEFAULT 'NORMAL', status ticket_status NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_messages (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), ticket_id UUID NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE, sender_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, sender_role TEXT NOT NULL, message TEXT NOT NULL, attachment_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_activity_logs (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, action TEXT NOT NULL, description TEXT NOT NULL, metadata JSONB, ip_address TEXT, admin_id UUID REFERENCES profiles(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_audit_logs (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), admin_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, action TEXT NOT NULL, target_type TEXT, target_id TEXT, before_data JSONB, after_data JSONB, ip_address TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS error_logs (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), level TEXT NOT NULL DEFAULT 'ERROR', message TEXT NOT NULL, stack TEXT, path TEXT, method TEXT, user_id UUID, metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS content_pages (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_by UUID REFERENCES profiles(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS content_sections (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), section TEXT UNIQUE NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_by UUID REFERENCES profiles(id) ON DELETE SET NULL);
CREATE OR REPLACE FUNCTION update_updated_at_column() RETURNS TRIGGER AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$ LANGUAGE plpgsql;
DO $$ DECLARE t TEXT; BEGIN FOR t IN SELECT table_name FROM information_schema.columns WHERE column_name = 'updated_at' AND table_schema = 'public' LOOP BEGIN EXECUTE format('DROP TRIGGER IF EXISTS set_updated_at ON %I', t); EXECUTE format('CREATE TRIGGER set_updated_at BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()', t); EXCEPTION WHEN OTHERS THEN NULL; END; END LOOP; END $$;
CREATE OR REPLACE FUNCTION handle_new_user() RETURNS TRIGGER AS $$ BEGIN INSERT INTO profiles (id, email, username, full_name, role, status) VALUES (NEW.id, NEW.email, COALESCE(NEW.raw_user_meta_data->>'username', split_part(NEW.email, '@', 1)), COALESCE(NEW.raw_user_meta_data->>'full_name', 'User'), 'USER', 'PAYMENT_PENDING'); INSERT INTO wallets (user_id) VALUES (NEW.id); RETURN NEW; END; $$ LANGUAGE plpgsql SECURITY DEFINER;
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
